import{_ as o,b as l,c as t,g as i}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"Nodes.js 22 带来的重大收益","description":"","frontmatter":{"title":"Nodes.js 22 带来的重大收益","author":"oasis","date":"2025-02-24T00:00:00.000Z"},"headers":[],"relativePath":"articles/nodejs/1.md","filePath":"articles/nodejs/1.md"}'),s={name:"articles/nodejs/1.md"};function n(a,e,d,r,u,p){return l(),t("div",null,[...e[0]||(e[0]=[i("<p>Node.js 22 放宽了 CommonJS 模块和 ESM 模块的互操作限制。允许在 CommonJS 模块通过 require(&quot;esm modules&quot;) 导入 ESM 文件。 但是在 esm 文件中存在顶层的 await ，则不允许使用 require() 导入。</p><p>这个特性带来的重大意义：大部分 NPM 包可以不用再提供 CommonJS 和 ESM 的产物，只提供 ESM 产物即可。ESM 产物已经被大部分浏览器所支持。 未来工程化可能会越来越简单了。</p><ul><li>执行 package.json 中的脚本 <ul><li>功能：新增实验性功能，通过 CLI 标志 noderun -- &lt;script-in-package-json&gt; 执行 package.json 中的脚本。</li><li>示例：node --run test 将执行 package.json 中的 test 命令。</li></ul></li></ul><p>TypeScript 5.8 的支持</p><ul><li>--module nodenext 标志： <ul><li>TypeScript 5.8 引入了 --module nodenext 标志。</li><li>当启用该标志时，TypeScript 不会报错，允许 CommonJS 文件通过 require() 导入 ESM 文件。</li></ul></li><li>注意事项： <ul><li>由于此特性可能被回溯到旧版本的 Node.js，目前没有稳定的 --module nodeXXXX 选项支持此行为。</li><li>未来版本的 TypeScript 可能会在 node20 下稳定支持此特性。</li></ul></li><li>建议： <ul><li>使用 Node.js 22 或更高版本的用户应启用 --module nodenext。</li><li>使用旧版本 Node.js 的用户应继续使用 --module node16 或更新到 --module node18。</li></ul></li></ul>",5)])])}const _=o(s,[["render",n]]);export{c as __pageData,_ as default};
